if not (isinstance(radius,int) and radius == max(rows//2, cols//2)):
    return (False, None)  # radius must be maximal torus Chebyshev distance
if not (isinstance(centers, (list, tuple)) and len(centers) == K):
    return (False, None)  # invalid centers
# Ensure centers are distinct and in bounds
seen = set()
for (r,c) in centers:
    if not (isinstance(r,int) and isinstance(c,int) and 1 <= r <= rows and 1 <= c <= cols):
        return (False, None)  # center out of bounds
    if (r,c) in seen:
        return (False, None)  # duplicate centers
    seen.add((r,c))
# Helper functions for torus distances
def torus_delta(a,b,m):
    d = abs(a-b)
    return min(d, m-d)
def d_inf_torus(cell, ctr):
    (i,j) = cell
    (p,q) = ctr
    return max(torus_delta(i,p,rows), torus_delta(j,q,cols))
# Precompute weights: w[i][j] = -max_k d_inf_torus((i,j), center_k)
w = [[None]*(cols+1) for _ in range(rows+1)]
for i in range(1, rows+1):
    for j in range(1, cols+1):
