        w[i][j] = -mx
# Enumerate all wrap-around rectangles (cyclic intervals on rows and cols)
# Build function to construct a cyclic interval set
def build_interval(start, length, m):
    return {((start - 1 + t) % m) + 1 for t in range(length)}
# Distance from a coordinate to a cyclic interval set on a circle of length m
def dist_to_interval(x, interval_set, m):
    if x in interval_set:
        return 0
    # scan outward up to m-1
    for d in range(1, m):
        xp = ((x - 1 + d) % m) + 1
        xm = ((x - 1 - d) % m) + 1
        if xp in interval_set or xm in interval_set:
            return d
    return m  # should not reach
# Chebyshev distance from a cell to a rectangle S defined by row_set, col_set
def d_inf_to_rect(i,j,row_set,col_set):
    dr = dist_to_interval(i, row_set, rows)
    dc = dist_to_interval(j, col_set, cols)
    return max(dr, dc)
brute_count = 0
