                # Build S cells
                # Compute min inside and max in ring
                min_inside = None
                # The ring includes all cells within Chebyshev distance <= radius from S, excluding S itself
                max_ring = None
                # Iterate all cells once, collecting
                for i in range(1, rows+1):
                    for j in range(1, cols+1):
                        inS = (i in row_set) and (j in col_set)
                        if inS:
                            val = w[i][j]
                            if min_inside is None or val < min_inside:
                                min_inside = val
                        else:
                            dS = d_inf_to_rect(i,j,row_set,col_set)
                            if dS <= radius:
                                val = w[i][j]
                                if max_ring is None or val > max_ring:
                                    max_ring = val
                # Assert min_inside and max_ring are defined: S has at least one cell; ring not empty because radius covers entire complement
                if min_inside is None:
                    return (False, None)  # impossible rectangle
                if max_ring is None:
                    return (False, None)  # radius must cover complement; should not happen
                if min_inside > max_ring:
                    brute_count += 1
# Now compute the closed-form based on largest circular gaps in rows and columns.
# Compute largest gap G_row: number of consecutive row indices without a center, maximized
row_positions = sorted({r for (r, c) in centers})
col_positions = sorted({c for (r, c) in centers})
# For rows
def largest_gap(positions, m):
    k = len(positions)
    # positions must be non-empty
    if k == 0:
        return m  # not possible here
    gaps = []
    for i in range(k-1):
        gaps.append(positions[i+1] - positions[i] - 1)
    gaps.append((positions[0] + m - positions[-1] - 1))
    return max(gaps)
G_row = largest_gap(row_positions, rows)
G_col = largest_gap(col_positions, cols)
def tri(t):
    return t*(t+1)//2
predicted = tri(G_row + 1) * tri(G_col + 1)
# Cross-check to enforce correctness and prevent trivial mismatches.
if brute_count != predicted:
    # If mismatch, reject.
    return (False, None)
return (True, predicted)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

